const page = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#121b39\">\n  <meta name=\"description\" content=\"Practice memorising exact passages with first-letter cues and progressive recall.\">\n  <title>FLOW — First Letter Practice</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='15' fill='%23121b39'/%3E%3Cpath d='M17 16h31v9H27v8h18v9H27v16H17z' fill='%23ffd45a'/%3E%3C/svg%3E\">\n  <style>\n    :root {\n      --ink: #121b39;\n      --ink-soft: #47506c;\n      --paper: #f7f8fc;\n      --card: #ffffff;\n      --line: #d9deeb;\n      --accent: #ffd45a;\n      --accent-strong: #f4b82f;\n      --blue: #3156d9;\n      --blue-soft: #eef2ff;\n      --good: #147a52;\n      --bad: #bf3b46;\n      --shadow: 0 18px 50px rgba(18, 27, 57, 0.10);\n    }\n\n    * { box-sizing: border-box; }\n\n    body {\n      margin: 0;\n      min-height: 100vh;\n      color: var(--ink);\n      background:\n        radial-gradient(circle at 8% 0%, rgba(255, 212, 90, .33), transparent 25rem),\n        linear-gradient(180deg, #f3f5fb 0, var(--paper) 28rem);\n      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n      font-size: 16px;\n      line-height: 1.5;\n    }\n\n    button, textarea, input { font: inherit; }\n    button { cursor: pointer; }\n\n    .sr-only {\n      position: absolute;\n      width: 1px;\n      height: 1px;\n      padding: 0;\n      margin: -1px;\n      overflow: hidden;\n      clip: rect(0, 0, 0, 0);\n      white-space: nowrap;\n      border: 0;\n    }\n\n    .shell {\n      width: min(1180px, calc(100% - 32px));\n      margin: 0 auto;\n      padding: 28px 0 54px;\n    }\n\n    header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 24px;\n      margin-bottom: 26px;\n    }\n\n    .brand { display: flex; align-items: center; gap: 13px; }\n    .brand-mark {\n      display: grid;\n      place-items: center;\n      width: 46px;\n      height: 46px;\n      border-radius: 13px;\n      color: var(--accent);\n      background: var(--ink);\n      font-weight: 900;\n      font-size: 1.45rem;\n      box-shadow: 0 7px 18px rgba(18, 27, 57, .18);\n    }\n    .brand-copy strong { display: block; font-size: 1.06rem; letter-spacing: .08em; }\n    .brand-copy span { color: var(--ink-soft); font-size: .88rem; }\n\n    .header-tools { display: flex; align-items: center; gap: 12px; }\n    .saved {\n      display: inline-flex;\n      align-items: center;\n      gap: 7px;\n      color: var(--ink-soft);\n      font-size: .88rem;\n    }\n    .saved::before {\n      content: \"\";\n      width: 8px;\n      height: 8px;\n      border-radius: 50%;\n      background: var(--good);\n    }\n    .settings-button {\n      min-height: 40px;\n      border: 1px solid var(--line);\n      border-radius: 11px;\n      padding: 8px 13px;\n      color: var(--ink);\n      background: rgba(255,255,255,.88);\n      font-weight: 800;\n    }\n    .settings-button:hover { border-color: #b9c1d6; background: white; }\n\n    .workspace {\n      display: grid;\n      grid-template-columns: minmax(300px, .83fr) minmax(430px, 1.35fr);\n      align-items: start;\n      gap: 22px;\n      transition: grid-template-columns .25s ease;\n    }\n\n    body.session-active .workspace { grid-template-columns: minmax(0, 1fr); }\n    body.session-active .setup-panel { display: none; }\n    body.session-active .practice-panel { width: min(900px, 100%); margin-inline: auto; }\n\n    .panel {\n      background: rgba(255,255,255,.92);\n      border: 1px solid rgba(217, 222, 235, .9);\n      border-radius: 22px;\n      box-shadow: var(--shadow);\n      overflow: hidden;\n    }\n\n    .panel-head {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n      padding: 19px 21px;\n      border-bottom: 1px solid var(--line);\n    }\n    .panel-head h1, .panel-head h2 { margin: 0; font-size: 1.02rem; }\n    .panel-actions { display: flex; align-items: center; gap: 8px; }\n    .header-action {\n      min-height: 36px;\n      border: 1px solid var(--line);\n      border-radius: 9px;\n      padding: 7px 11px;\n      color: var(--ink-soft);\n      background: white;\n      font-size: .8rem;\n      font-weight: 800;\n    }\n    .header-action:hover { color: var(--ink); border-color: #b9c1d6; }\n    .step {\n      color: var(--blue);\n      background: var(--blue-soft);\n      border-radius: 999px;\n      padding: 4px 9px;\n      font-size: .76rem;\n      font-weight: 800;\n      letter-spacing: .07em;\n      text-transform: uppercase;\n    }\n\n    .editor-body { padding: 20px; }\n    label { display: block; color: var(--ink-soft); font-size: .84rem; font-weight: 700; margin-bottom: 7px; }\n    .title-input, textarea {\n      width: 100%;\n      color: var(--ink);\n      background: #fbfcff;\n      border: 1px solid var(--line);\n      border-radius: 12px;\n      outline: none;\n      transition: border-color .18s, box-shadow .18s;\n    }\n    .title-input { height: 44px; padding: 0 13px; margin-bottom: 16px; }\n    textarea { min-height: 224px; resize: vertical; padding: 13px; line-height: 1.65; }\n    .title-input:focus, textarea:focus {\n      border-color: var(--blue);\n      box-shadow: 0 0 0 3px rgba(49, 86, 217, .12);\n    }\n    .hint { color: var(--ink-soft); font-size: .8rem; margin: 8px 1px 17px; }\n    .primary {\n      width: 100%;\n      border: 0;\n      border-radius: 12px;\n      padding: 12px 16px;\n      color: white;\n      background: var(--ink);\n      font-weight: 800;\n      box-shadow: 0 6px 14px rgba(18,27,57,.16);\n    }\n    .primary:hover { background: #1d2a55; }\n\n    .mini-rule {\n      display: grid;\n      grid-template-columns: auto 1fr;\n      gap: 10px;\n      margin-top: 18px;\n      padding-top: 17px;\n      border-top: 1px solid var(--line);\n      color: var(--ink-soft);\n      font-size: .82rem;\n    }\n    .mini-rule b { color: var(--ink); }\n    .keycap {\n      align-self: start;\n      border: 1px solid var(--line);\n      border-bottom-width: 3px;\n      border-radius: 7px;\n      padding: 1px 7px;\n      color: var(--ink);\n      background: white;\n      font-size: .76rem;\n      font-weight: 800;\n    }\n\n    .practice-top { padding: 20px 21px 0; }\n    .understand-panel {\n      padding: 17px;\n      border: 1px solid #cfd8f7;\n      border-radius: 15px;\n      background: linear-gradient(135deg, #f2f5ff, #fafbff);\n    }\n    .understand-head {\n      display: flex;\n      align-items: flex-start;\n      justify-content: space-between;\n      gap: 18px;\n      margin-bottom: 13px;\n    }\n    .understand-head h3 { margin: 0 0 3px; font-size: 1rem; }\n    .understand-head p { margin: 0; color: var(--ink-soft); font-size: .82rem; }\n    .ai-badge {\n      flex: 0 0 auto;\n      padding: 4px 9px;\n      border-radius: 999px;\n      color: #2947b6;\n      background: #e1e8ff;\n      font-size: .74rem;\n      font-weight: 850;\n      letter-spacing: .06em;\n      text-transform: uppercase;\n    }\n    .key-row {\n      display: grid;\n      grid-template-columns: minmax(180px, 1fr) auto auto;\n      gap: 8px;\n      align-items: center;\n    }\n    .key-row input {\n      width: 100%;\n      min-height: 42px;\n      border: 1px solid #c8d2f2;\n      border-radius: 10px;\n      padding: 0 12px;\n      color: var(--ink);\n      background: white;\n      outline: none;\n    }\n    .key-row input:focus { border-color: var(--blue); box-shadow: 0 0 0 3px rgba(49,86,217,.12); }\n    .key-control, .ai-action {\n      min-height: 42px;\n      border-radius: 10px;\n      padding: 0 13px;\n      font-weight: 800;\n    }\n    .key-control { border: 1px solid #c8d2f2; color: var(--ink-soft); background: white; }\n    .ai-action { border: 0; color: white; background: var(--blue); }\n    .ai-action:disabled { opacity: .65; cursor: wait; }\n    .key-note {\n      margin: 9px 0 0;\n      color: var(--ink-soft);\n      font-size: .76rem;\n      line-height: 1.45;\n    }\n    .key-note strong { color: var(--ink); }\n    .ai-status { min-height: 20px; margin: 8px 0 0; color: #2947b6; font-size: .8rem; font-weight: 750; }\n    .ai-status.error { color: var(--bad); }\n    .ai-result {\n      margin-top: 13px;\n      padding: 16px;\n      border: 1px solid #dbe1f2;\n      border-radius: 12px;\n      background: white;\n    }\n    .ai-result[hidden] { display: none; }\n    .ai-result-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 9px; }\n    .ai-result h4 { margin: 0; font-family: Georgia, serif; font-size: 1.1rem; }\n    .ai-output { margin: 0; color: #27304d; white-space: pre-wrap; line-height: 1.65; font-size: .92rem; }\n    .dialog-shell {\n      width: min(620px, calc(100% - 28px));\n      max-height: min(82vh, 760px);\n      margin: auto;\n      padding: 0;\n      color: var(--ink);\n      background: white;\n      border: 1px solid var(--line);\n      border-radius: 20px;\n      box-shadow: 0 28px 90px rgba(18,27,57,.28);\n      overflow: auto;\n    }\n    .dialog-shell::backdrop { background: rgba(18,27,57,.52); backdrop-filter: blur(4px); }\n    .dialog-head {\n      position: sticky;\n      top: 0;\n      z-index: 1;\n      display: flex;\n      align-items: flex-start;\n      justify-content: space-between;\n      gap: 18px;\n      padding: 20px 21px;\n      background: rgba(255,255,255,.96);\n      border-bottom: 1px solid var(--line);\n    }\n    .dialog-head h2 { margin: 0 0 3px; font-family: Georgia, serif; font-size: 1.3rem; }\n    .dialog-head p { margin: 0; color: var(--ink-soft); font-size: .84rem; }\n    .dialog-close {\n      flex: 0 0 auto;\n      width: 36px;\n      height: 36px;\n      border: 1px solid var(--line);\n      border-radius: 10px;\n      color: var(--ink-soft);\n      background: white;\n      font-size: 1.2rem;\n      line-height: 1;\n    }\n    .dialog-body { padding: 21px; }\n    .settings-card { padding: 17px; border: 1px solid var(--line); border-radius: 15px; background: #fbfcff; }\n    .settings-card h3 { margin: 0 0 4px; font-size: 1rem; }\n    .settings-card > p { margin: 0 0 15px; color: var(--ink-soft); font-size: .84rem; }\n    .ai-enabled-note { display: none; margin: 11px 0 0; color: var(--good); font-size: .8rem; font-weight: 800; }\n    body.ai-enabled .ai-enabled-note { display: block; }\n    #openAIComprehension[hidden] { display: none; }\n    .stage-guide {\n      display: flex;\n      align-items: flex-start;\n      justify-content: space-between;\n      gap: 20px;\n      margin-bottom: 16px;\n      padding: 13px 15px;\n      border-left: 4px solid var(--accent-strong);\n      border-radius: 0 10px 10px 0;\n      background: #fff9e7;\n    }\n    .stage-guide strong { display: block; margin-bottom: 2px; font-size: .88rem; }\n    .stage-guide p { margin: 0; color: var(--ink-soft); font-size: .82rem; }\n    .stage-count { flex: 0 0 auto; color: #7b5a00; font-size: .76rem; font-weight: 850; text-transform: uppercase; letter-spacing: .06em; }\n    .passage-name { margin: 0 0 4px; font-family: Georgia, serif; font-size: clamp(1.45rem, 3vw, 2rem); }\n    .metrics { display: flex; flex-wrap: wrap; gap: 9px 18px; color: var(--ink-soft); font-size: .84rem; }\n    .metrics strong { color: var(--ink); }\n\n    .mode-tabs {\n      display: grid;\n      grid-template-columns: repeat(4, 1fr);\n      gap: 5px;\n      margin: 19px 0 0;\n      padding: 5px;\n      background: #eef1f8;\n      border-radius: 13px;\n    }\n    .mode-tab {\n      min-height: 42px;\n      border: 0;\n      border-radius: 9px;\n      color: var(--ink-soft);\n      background: transparent;\n      font-size: .83rem;\n      font-weight: 800;\n    }\n    .mode-tab .stage-number {\n      display: inline-grid;\n      place-items: center;\n      width: 22px;\n      height: 22px;\n      margin-right: 5px;\n      border-radius: 50%;\n      color: #68728d;\n      background: rgba(255,255,255,.55);\n      font-size: .72rem;\n    }\n    .mode-tab[aria-selected=\"true\"] {\n      color: var(--ink);\n      background: white;\n      box-shadow: 0 2px 8px rgba(18,27,57,.10);\n    }\n    .mode-tab[aria-selected=\"true\"] .stage-number { color: var(--ink); background: var(--accent); }\n    .mode-tab:focus-visible, .word:focus-visible, button:focus-visible {\n      outline: 3px solid rgba(49, 86, 217, .35);\n      outline-offset: 2px;\n    }\n\n    .cue-stage { padding: 18px 21px 13px; }\n    .study-card {\n      position: relative;\n      min-height: 220px;\n      padding: clamp(22px, 4vw, 34px);\n      overflow: auto;\n      color: #111936;\n      background:\n        linear-gradient(90deg, transparent 0 36px, rgba(223,72,82,.16) 36px 38px, transparent 38px),\n        repeating-linear-gradient(#fff 0 35px, #dce5f6 36px);\n      border: 1px solid var(--line);\n      border-radius: 17px;\n      font-family: Georgia, \"Times New Roman\", serif;\n      font-size: clamp(1.2rem, 2.6vw, 1.6rem);\n      line-height: 1.54;\n      letter-spacing: .035em;\n      display: grid;\n      align-items: center;\n    }\n    .cue-content { white-space: pre-wrap; }\n    .word {\n      display: inline;\n      margin: 0;\n      padding: 1px 2px;\n      border: 0;\n      border-radius: 4px;\n      color: inherit;\n      background: transparent;\n      font-family: inherit;\n      font-size: inherit;\n      line-height: inherit;\n      text-align: left;\n    }\n    .word:hover { background: var(--accent); }\n    .word.revealed { color: #142c91; background: #e5eafe; }\n    .cold-space {\n      display: inline-block;\n      width: .72em;\n      height: .85em;\n      margin: 0 1px;\n      border-bottom: 2px solid #aeb8d0;\n      vertical-align: baseline;\n    }\n\n    .card-help {\n      display: flex;\n      justify-content: space-between;\n      gap: 12px;\n      margin-top: 10px;\n      color: var(--ink-soft);\n      font-size: .8rem;\n    }\n    .help-actions { display: flex; gap: 14px; flex-wrap: wrap; }\n    .text-action {\n      border: 0;\n      padding: 0;\n      color: var(--blue);\n      background: none;\n      font-weight: 800;\n    }\n\n    .chunk-nav {\n      display: grid;\n      grid-template-columns: 1fr auto 1fr;\n      align-items: center;\n      gap: 12px;\n      margin-top: 15px;\n    }\n    .chunk-nav button {\n      width: max-content;\n      border: 1px solid var(--line);\n      border-radius: 10px;\n      padding: 8px 12px;\n      color: var(--ink);\n      background: white;\n      font-weight: 800;\n    }\n    .chunk-nav button:last-child { justify-self: end; }\n    .chunk-nav button:disabled { opacity: .4; cursor: not-allowed; }\n    .chunk-indicator { color: var(--ink-soft); font-size: .82rem; font-weight: 800; }\n\n    .recall {\n      margin: 4px 21px 21px;\n      padding: 18px;\n      background: #f6f8fd;\n      border: 1px solid var(--line);\n      border-radius: 16px;\n    }\n    .recall-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 10px; }\n    .recall h3 { margin: 0; font-size: .95rem; }\n    .recall textarea { min-height: 106px; background: white; }\n    .speech-row {\n      display: flex;\n      align-items: center;\n      gap: 11px;\n      margin: 0 0 11px;\n      padding: 10px 12px;\n      border: 1px solid var(--line);\n      border-radius: 12px;\n      background: white;\n    }\n    .mic-button {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      min-height: 42px;\n      border: 0;\n      border-radius: 999px;\n      padding: 0 16px;\n      color: white;\n      background: var(--ink);\n      font-weight: 850;\n      white-space: nowrap;\n    }\n    .mic-button svg { width: 18px; height: 18px; fill: currentColor; }\n    .mic-button.listening { background: var(--bad); box-shadow: 0 0 0 5px rgba(191,59,70,.13); }\n    .mic-button.listening svg { animation: micPulse 1s ease-in-out infinite; }\n    .mic-button:disabled { opacity: .5; cursor: not-allowed; }\n    .speech-copy { min-width: 0; }\n    .speech-status { margin: 0; color: var(--ink); font-size: .86rem; font-weight: 800; }\n    .speech-note { margin: 1px 0 0; color: var(--ink-soft); font-size: .74rem; }\n    @keyframes micPulse { 50% { transform: scale(1.18); } }\n    .recall-actions { display: flex; align-items: center; gap: 10px; margin-top: 11px; }\n    .check {\n      border: 0;\n      border-radius: 10px;\n      padding: 9px 15px;\n      color: white;\n      background: var(--blue);\n      font-weight: 800;\n    }\n    .clear {\n      border: 1px solid var(--line);\n      border-radius: 10px;\n      padding: 8px 13px;\n      color: var(--ink-soft);\n      background: white;\n      font-weight: 750;\n    }\n    .score { margin-left: auto; font-size: .87rem; font-weight: 800; }\n    .feedback { display: none; margin-top: 13px; padding-top: 13px; border-top: 1px solid var(--line); }\n    .feedback.visible { display: block; }\n    .feedback-summary { font-weight: 800; margin-bottom: 8px; }\n    .feedback-words { line-height: 2; }\n    .feedback-words span { display: inline-block; margin: 2px 3px 2px 0; padding: 0 5px; border-radius: 5px; }\n    .correct { color: var(--good); background: #e3f6ee; }\n    .wrong { color: var(--bad); background: #fdebed; text-decoration: line-through; }\n    .missing { color: #8b4d00; background: #fff0cc; }\n\n    body.focus-mode { background: var(--ink); }\n    body.focus-mode header,\n    body.focus-mode .setup-panel,\n    body.focus-mode .panel-head,\n    body.focus-mode .recall { display: none; }\n    body.focus-mode .shell { width: min(940px, calc(100% - 28px)); padding-top: 5vh; }\n    body.focus-mode .workspace { display: block; }\n    body.focus-mode .practice-panel { width: 100%; box-shadow: 0 24px 80px rgba(0,0,0,.35); }\n    body.focus-mode .practice-top { padding-top: 24px; }\n\n    .empty-state {\n      display: none;\n      min-height: 278px;\n      place-items: center;\n      padding: 30px;\n      color: var(--ink-soft);\n      text-align: center;\n    }\n\n    .toast {\n      position: fixed;\n      left: 50%;\n      bottom: 24px;\n      z-index: 10;\n      transform: translate(-50%, 20px);\n      padding: 10px 15px;\n      border-radius: 999px;\n      color: white;\n      background: var(--ink);\n      box-shadow: var(--shadow);\n      opacity: 0;\n      pointer-events: none;\n      transition: opacity .2s, transform .2s;\n      font-size: .88rem;\n      font-weight: 700;\n    }\n    .toast.show { opacity: 1; transform: translate(-50%, 0); }\n\n    @media (max-width: 860px) {\n      .workspace { grid-template-columns: 1fr; }\n      .editor-body { display: grid; grid-template-columns: 1fr 1fr; gap: 0 15px; }\n      .editor-body .passage-wrap, .editor-body .hint, .editor-body .primary, .editor-body .mini-rule { grid-column: 1 / -1; }\n      textarea { min-height: 170px; }\n      body.session-active .workspace { display: block; }\n    }\n\n    @media (max-width: 560px) {\n      .shell { width: min(100% - 18px, 1180px); padding-top: 16px; }\n      header { margin: 0 5px 16px; }\n      .saved { display: none; }\n      .header-tools { gap: 6px; }\n      .panel { border-radius: 17px; }\n      .editor-body { display: block; }\n      .mode-tabs { grid-template-columns: 1fr 1fr; }\n      .mode-tab { text-align: left; padding-left: 12px; }\n      .key-row { grid-template-columns: 1fr auto; }\n      .key-row .ai-action { grid-column: 1 / -1; }\n      .study-card { min-height: 245px; padding-left: 30px; }\n      .card-help { flex-direction: column; }\n      .recall-actions { flex-wrap: wrap; }\n      .speech-row { align-items: flex-start; }\n      .score { width: 100%; margin: 2px 0 0; }\n    }\n\n    @media (prefers-reduced-motion: reduce) {\n      *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; }\n    }\n    /* A quiet writing desk: restrained chrome, generous reading space. */\n    :root { --paper: #f2f4f8; --line: #e0e5ed; --ink-soft: #58637a; --blue: #385ad5; --shadow: 0 8px 32px rgba(23,36,67,.045); }\n    body { background: var(--paper); }\n    .shell { width: min(1280px, calc(100% - 64px)); padding: 26px 0 48px; }\n    header { margin-bottom: 30px; padding-bottom: 23px; border-bottom: 1px solid var(--line); }\n    .brand-mark { width: 38px; height: 38px; border-radius: 11px; box-shadow: none; font-size: 1.2rem; }\n    .brand-copy strong { letter-spacing: .16em; font-size: .95rem; }\n    .brand-copy span { font-size: .8125rem; }\n    .saved { font-size: .8125rem; }\n    .saved::before { display: none; }\n    .settings-button { background: transparent; font-size: .875rem; font-weight: 650; }\n    .workspace { grid-template-columns: minmax(280px, .78fr) minmax(0, 1.8fr); gap: 28px; }\n    .panel { border-radius: 18px; background: white; border-color: var(--line); }\n    .setup-panel { background: transparent; box-shadow: none; border: 0; }\n    .setup-panel .panel-head { padding: 12px 0 18px; border: 0; }\n    .setup-panel .panel-head h1 { font-size: 1.3rem; letter-spacing: -.03em; }\n    .step { font-size: .75rem; background: #e6eaf3; color: var(--ink-soft); }\n    .editor-body { padding: 0; }\n    .editor-intro { margin: 0 0 24px; color: var(--ink-soft); font-size: .9375rem; }\n    label { font-size: .875rem; font-weight: 600; }\n    .title-input, textarea { background: white; border-radius: 10px; }\n    .title-input { margin-bottom: 20px; height: 46px; }\n    #sourceText { min-height: 265px; font-size: 1rem; }\n    .hint { font-size: .8125rem; margin: 10px 0 18px; }\n    .editor-count { display: flex; justify-content: space-between; gap: 8px; margin-top: 8px; font-size: .8125rem; color: var(--ink-soft); }\n    .primary { border-radius: 10px; min-height: 48px; font-weight: 650; box-shadow: none; }\n    .mini-rule { font-size: .875rem; border: 0; margin-top: 10px; }\n    .practice-panel > .panel-head { padding: 17px 28px; }\n    .practice-panel > .panel-head h2 { font-size: .75rem; text-transform: uppercase; letter-spacing: .13em; color: var(--ink-soft); }\n    .panel-actions { flex-wrap: wrap; justify-content: flex-end; }\n    .header-action { font-size: .875rem; font-weight: 550; border-color: transparent; background: transparent; }\n    #openAIComprehension { color: var(--blue); background: var(--blue-soft); }\n    .practice-top { display: flex; flex-direction: column; padding: 27px 32px 0; }\n    .passage-name { order: 0; font-size: clamp(1.8rem, 2.8vw, 2.4rem); font-weight: 500; letter-spacing: -.035em; line-height: 1.2; margin-bottom: 12px; overflow-wrap: anywhere; }\n    .metrics { order: 1; font-size: .8125rem; gap: 7px 18px; }\n    .metrics strong { font-weight: 600; }\n    .mode-tabs { order: 2; background: #f1f3f8; padding: 5px; margin: 26px 0 0; border-radius: 12px; }\n    .mode-tab { font-size: .875rem; font-weight: 650; min-height: 48px; }\n    .mode-tab[aria-selected=\"true\"] { box-shadow: 0 2px 5px #121b3910; }\n    .mode-tab .stage-number { background: transparent; }\n    .mode-tab[aria-selected=\"true\"] .stage-number { color: white; background: var(--ink); }\n    .stage-guide { order: 3; background: transparent; padding: 18px 0 0; margin: 0; border: 0; gap: 12px; }\n    .stage-guide strong { font-size: .9375rem; font-weight: 650; }\n    .stage-guide p { font-size: .875rem; }\n    .stage-count { color: var(--ink-soft); font-size: .75rem; letter-spacing: .04em; padding-top: 3px; }\n    .cue-stage { padding: 20px 32px 22px; }\n    .study-card { min-height: 228px; padding: 32px; background: #f8f9fc; border: 1px solid #e9edf5; border-radius: 12px; font-size: clamp(1.45rem, 2.7vw, 2rem); line-height: 1.9; letter-spacing: .015em; overflow-wrap: anywhere; }\n    .word { min-width: .55em; padding: 2px 3px; border-radius: 5px; transition: background .15s; }\n    .word:hover { background: #ffe596; }\n    .card-help { font-size: .8125rem; margin-top: 12px; flex-wrap: wrap; }\n    .text-action { font-weight: 600; }\n    .chunk-nav { margin-top: 22px; }\n    .chunk-nav button { font-size: .875rem; font-weight: 600; min-height: 42px; }\n    .chunk-center { display: grid; justify-items: center; gap: 7px; }\n    .chunk-indicator { font-size: .8125rem; font-weight: 550; }\n    .chunk-dots { display: flex; gap: 5px; max-width: 180px; flex-wrap: wrap; justify-content: center; }\n    .chunk-dots span { width: 16px; height: 4px; background: #e2e6ef; border-radius: 4px; }\n    .chunk-dots .current { background: var(--blue); }\n    .chunk-dots .checked { background: var(--good); }\n    .recall { margin: 0; padding: 24px 32px 28px; border: 0; border-top: 1px solid var(--line); border-radius: 0; background: white; }\n    .recall-head { margin-bottom: 14px; }\n    .recall h3 { font-size: 1rem; font-weight: 650; }\n    .recall-caption { color: var(--ink-soft); font-size: .875rem; margin: 3px 0 0; }\n    .speech-row { padding: 0; border: 0; background: none; align-items: flex-start; }\n    .mic-button { border-radius: 9px; font-size: .875rem; font-weight: 650; padding: 0 13px; background: #eef2fb; color: var(--blue); }\n    .mic-button.listening { color: white; }\n    .speech-status { font-size: .8125rem; font-weight: 500; }\n    .speech-note { font-size: .75rem; }\n    .recall textarea { min-height: 112px; background: #fafbfe; font-size: 1rem; }\n    .check, .clear { min-height: 44px; font-size: .875rem; font-weight: 650; }\n    .score { font-size: .875rem; }\n    .feedback { padding-top: 18px; }\n    .feedback-summary { font-size: .9375rem; font-weight: 600; }\n    .feedback-legend { display: flex; gap: 12px; flex-wrap: wrap; margin: 12px 0 0; font-size: .8125rem; color: var(--ink-soft); }\n    .feedback-legend span { padding: 1px 6px; border-radius: 4px; }\n    .practice-footer { display: flex; justify-content: space-between; align-items: center; padding: 16px 32px; gap: 12px; border-top: 1px solid var(--line); background: #fafbfe; }\n    .practice-panel { display: flex; flex-direction: column; }\n    .practice-panel > .panel-head { order: 0; }\n    .practice-top { order: 1; }\n    .cue-stage { order: 2; }\n    .practice-footer { order: 3; }\n    .recall { order: 4; }\n    .primary:disabled { opacity: .5; cursor: not-allowed; }\n    .practice-footer p { margin: 0; color: var(--ink-soft); font-size: .8125rem; }\n    .advance { border: 0; border-radius: 9px; background: var(--ink); color: white; padding: 11px 16px; min-height: 44px; font-size: .875rem; font-weight: 650; }\n    .dialog-head h2 { font-family: inherit; font-size: 1.2rem; letter-spacing: -.02em; }\n    .dialog-head p, .settings-card > p, .understand-head p { font-size: .9375rem; }\n    .key-note, .ai-status { font-size: .8125rem; }\n    .dialog-close { width: 44px; height: 44px; }\n    .understand-panel { background: #f8f9fe; }\n    .focus-exit { display: none; }\n    body.focus-mode { background: #e9edf5; }\n    body.focus-mode .focus-exit { display: block; position: fixed; top: 18px; right: 22px; z-index: 5; background: white; }\n    body.focus-mode .shell { padding-top: 80px; }\n    body.focus-mode .practice-panel { box-shadow: var(--shadow); }\n    body.focus-mode .study-card { min-height: 38vh; }\n    body.session-active .practice-panel { width: min(900px, 100%); }\n    @media (max-width: 1000px) {\n      .shell { width: calc(100% - 36px); }\n      .workspace { grid-template-columns: minmax(250px, .8fr) minmax(0, 1.4fr); gap: 20px; }\n      .practice-top, .cue-stage { padding-left: 22px; padding-right: 22px; }\n      .practice-panel > .panel-head, .recall, .practice-footer { padding-left: 22px; padding-right: 22px; }\n      .panel-head { flex-wrap: wrap; }\n      .editor-body { display: block; }\n    }\n    @media (max-width: 760px) {\n      .workspace { grid-template-columns: 1fr; }\n      .setup-panel { max-width: 580px; width: 100%; margin: auto; }\n      body:not(.session-active) .practice-panel { display: none; }\n      header { margin-bottom: 22px; }\n      .saved { display: none; }\n      #sourceText { min-height: 240px; }\n      .panel-actions { gap: 2px; }\n      .mode-tabs { grid-template-columns: repeat(4, minmax(0, 1fr)); }\n      .mode-tab { text-align: center; padding: 6px 2px; font-size: .8125rem; }\n      .mode-tab .stage-number { display: block; margin: 0 auto 3px; }\n      .stage-count { display: none; }\n      .study-card { padding: 22px; min-height: 210px; }\n      .speech-row { flex-direction: column; }\n      .practice-footer p { max-width: 160px; }\n      .practice-top, .cue-stage, .recall, .practice-footer { padding-left: 18px; padding-right: 18px; }\n      .recall-actions .score { width: auto; margin-left: auto; }\n      .key-row { grid-template-columns: minmax(0, 1fr) auto; }\n      #forgetKey { grid-column: 1 / -1; }\n      .understand-head { flex-direction: column; gap: 8px; }\n    }\n    [hidden] { display: none !important; }\n    select { font: inherit; color: var(--ink); background: white; border: 1px solid var(--line); border-radius: 9px; padding: 10px; max-width: 100%; }\n    .library-dialog { width: min(900px, calc(100% - 24px)); }\n    .library-toolbar, .library-footer, .session-queue, .test-tools { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }\n    .library-toolbar { justify-content: space-between; margin: 0 0 16px; }\n    .library-toolbar p, .library-footer p { margin: 0; font-size: .875rem; color: var(--ink-soft); }\n    .library-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; max-height: 330px; overflow: auto; margin-bottom: 20px; }\n    .library-item { display: flex; gap: 12px; align-items: flex-start; padding: 16px; border: 1px solid var(--line); border-radius: 12px; margin: 0; cursor: pointer; background: white; }\n    .library-item:has(input:checked) { background: #f0f4ff; border-color: #8fa4ee; }\n    .library-item input { margin: 5px 0 0; width: 18px; height: 18px; flex-shrink: 0; accent-color: var(--blue); }\n    .library-item strong { display: block; font-size: .9375rem; color: var(--ink); overflow-wrap: anywhere; }\n    .library-item small { display: block; color: var(--ink-soft); font-weight: 400; font-size: .8125rem; margin-top: 6px; }\n    .library-item .preview-text { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n    .import-box { border: 1px solid var(--line); border-radius: 12px; padding: 16px; background: #f8f9fc; }\n    .import-box summary { cursor: pointer; font-weight: 650; }\n    .import-box label { margin-top: 16px; }\n    .import-box textarea { min-height: 180px; }\n    .import-preview { max-height: 160px; overflow: auto; padding-left: 22px; font-size: .875rem; }\n    .library-footer { position: sticky; bottom: 0; justify-content: space-between; padding: 18px 22px; background: white; border-top: 1px solid var(--line); }\n    .session-queue { order: 0; padding: 14px 28px; background: #f5f7fc; border-bottom: 1px solid var(--line); }\n    .session-queue label { margin: 0; font-size: .8125rem; }\n    .session-queue select { flex: 1; min-width: 130px; font-size: .875rem; }\n    .session-queue .header-action { border-color: var(--line); background: white; }\n    .library-invite { display: block; width: 100%; text-align: left; border: 1px solid #ccd6f3; border-radius: 12px; padding: 15px; margin: 0 0 24px; background: #eef2ff; color: var(--ink); }\n    .library-invite strong, .library-invite span { display: block; }\n    .library-invite span { margin-top: 4px; color: var(--ink-soft); font-size: .875rem; }\n    .test-tools { justify-content: space-between; margin: 16px 0; }\n    .input-method { display: inline-flex; background: #edf0f7; padding: 4px; border-radius: 10px; gap: 4px; }\n    .input-method button { border: 0; border-radius: 7px; padding: 8px 14px; font-weight: 600; color: var(--ink-soft); background: transparent; font-size: .875rem; }\n    .input-method button[aria-pressed=\"true\"] { color: var(--ink); background: white; box-shadow: 0 1px 5px #121b3912; }\n    .hide-cues { display: flex; gap: 7px; align-items: center; font-weight: 500; margin: 0; }\n    .hide-cues input { accent-color: var(--blue); width: 17px; height: 17px; }\n    .test-context { font-size: .8125rem; color: var(--blue); margin: 8px 0 0; }\n    .test-cues-hidden .cue-content { visibility: hidden; }\n    .test-cues-hidden .study-card::after { content: 'Cues hidden · Give your memory a moment'; position: absolute; inset: 0; display: grid; place-items: center; padding: 30px; text-align: center; font: 500 .9375rem/1.6 system-ui; color: var(--ink-soft); }\n    .test-cues-hidden .help-actions { visibility: hidden; }\n    .result-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 14px 0; }\n    .result-stats div { border-radius: 9px; padding: 12px; background: #f2f5fa; color: var(--ink-soft); font-size: .8125rem; }\n    .result-stats strong { display: block; font-size: 1.25rem; color: var(--ink); }\n    .result-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 18px; }\n    .speech-row { padding: 16px; background: #f3f6ff; border-radius: 10px; }\n    .recall-head { align-items: flex-start; }\n    .recall-head .score { white-space: nowrap; background: #edf4ff; border-radius: 9px; padding: 6px 10px; }\n    .recall-head .score:empty { display: none; }\n    .feedback { scroll-margin-top: 24px; }\n    body.focus-mode .session-queue { display: none; }\n    @media(max-width: 600px) { .library-list { grid-template-columns: 1fr; } .header-tools { flex-wrap: wrap; justify-content: flex-end; } .brand-copy span { display: none; } .session-queue { padding: 12px 18px; } .session-queue label { width: 100%; } .result-stats div { padding: 8px; } }\n  </style>\n</head>\n<body>\n  <main class=\"shell\">\n    <header>\n      <div class=\"brand\">\n        <div class=\"brand-mark\" aria-hidden=\"true\">F</div>\n        <div class=\"brand-copy\"><strong>FLOW</strong><span>A little practice. A lasting memory.</span></div>\n      </div>\n      <div class=\"header-tools\">\n        <div class=\"saved\" id=\"savedStatus\">Saved on this device</div>\n        <button class=\"settings-button\" id=\"openLibrary\" type=\"button\">Passages</button>\n        <button class=\"settings-button\" id=\"openSettings\" type=\"button\">Settings</button>\n      </div>\n    </header>\n\n    <div class=\"workspace\">\n      <section class=\"panel setup-panel\" aria-labelledby=\"editor-title\">\n        <div class=\"panel-head\">\n          <h1 id=\"editor-title\">Your passage</h1>\n          <span class=\"step\">Set up</span>\n        </div>\n        <div class=\"editor-body\">\n          <button class=\"library-invite\" id=\"libraryInvite\" type=\"button\"><strong>Your passage library →</strong><span>Paste several passages once. Choose what to practise.</span></button>\n          <p class=\"editor-intro\">Give your words a place to stick. Add a passage, then gradually let go of the cues.</p>\n          <div>\n            <label for=\"passageTitle\">Passage name</label>\n            <input class=\"title-input\" id=\"passageTitle\" value=\"The value of practice\" autocomplete=\"off\">\n          </div>\n          <div class=\"passage-wrap\">\n            <label for=\"sourceText\">Text to memorise</label>\n            <textarea id=\"sourceText\" spellcheck=\"true\">We are what we repeatedly do. Excellence, then, is not an act, but a habit.\n\nPractice does not make perfect. Only perfect practice makes perfect.</textarea>\n          </div>\n          <div class=\"editor-count\"><span id=\"wordCount\">0 words</span><span id=\"partCount\">1 practice part</span></div>\n          <p class=\"hint\">Your passage is saved on this device.</p>\n          <button class=\"primary\" id=\"generateBtn\" type=\"button\">Start practising →</button>\n          <div class=\"mini-rule\">\n            <span class=\"keycap\">Tip</span>\n            <span>Start with the full text. Fade a few words, use first letters, then try from memory.</span>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"panel practice-panel\" aria-labelledby=\"practice-title\">\n        <nav class=\"session-queue\" aria-label=\"Selected passages\" id=\"sessionQueue\" hidden><label for=\"queueSelect\" id=\"queueLabel\">Your selection</label><select id=\"queueSelect\"></select><button class=\"header-action\" id=\"nextPassage\" type=\"button\">Next passage →</button></nav>\n        <div class=\"panel-head\">\n          <h2 id=\"practice-title\">Practice</h2>\n          <div class=\"panel-actions\">\n            <button class=\"header-action\" id=\"openAIComprehension\" type=\"button\" hidden>AI comprehension</button>\n            <button class=\"header-action\" id=\"editPassage\" type=\"button\">Edit passage</button>\n            <button class=\"header-action\" id=\"focusMode\" type=\"button\">Focus mode</button>\n          </div>\n        </div>\n\n        <div class=\"practice-top\">\n          <div class=\"stage-guide\">\n            <div>\n              <strong id=\"stageTitle\">Initial-letter retrieval</strong>\n              <p id=\"stageHelp\">Say each word aloud. Tap a letter only when you get stuck.</p>\n            </div>\n            <span class=\"stage-count\" id=\"stageCount\">Stage 3 of 4</span>\n          </div>\n          <h2 class=\"passage-name\" id=\"displayTitle\">The value of practice</h2>\n          <div class=\"metrics\" aria-live=\"polite\">\n            <span>Part <strong id=\"chunkStat\">1 of 1</strong></span>\n            <span>Match <strong id=\"accuracyStat\">—</strong></span>\n            <span><strong id=\"revealedCount\">0</strong> hints revealed</span>\n          </div>\n          <div class=\"mode-tabs\" role=\"tablist\" aria-label=\"Cue strength\">\n            <button class=\"mode-tab\" role=\"tab\" aria-selected=\"false\" data-mode=\"full\"><span class=\"stage-number\">1</span>Read</button>\n            <button class=\"mode-tab\" role=\"tab\" aria-selected=\"false\" data-mode=\"fade\"><span class=\"stage-number\">2</span>Fade</button>\n            <button class=\"mode-tab\" role=\"tab\" aria-selected=\"true\" data-mode=\"letters\"><span class=\"stage-number\">3</span>Initials</button>\n            <button class=\"mode-tab\" role=\"tab\" aria-selected=\"false\" data-mode=\"cold\"><span class=\"stage-number\">4</span>Recall</button>\n          </div>\n        </div>\n\n        <div class=\"cue-stage\">\n          <div class=\"study-card\" id=\"studyCard\" aria-label=\"Passage cues\">\n            <div class=\"cue-content\" id=\"cueContent\"></div>\n          </div>\n          <div class=\"card-help\">\n            <span id=\"cueHint\">Tap a letter to reveal its word.</span>\n            <div class=\"help-actions\">\n              <button class=\"text-action\" id=\"revealChunk\" type=\"button\">Reveal this phrase</button>\n              <button class=\"text-action\" id=\"resetReveals\" type=\"button\">Hide reveals</button>\n            </div>\n          </div>\n          <nav class=\"chunk-nav\" aria-label=\"Passage chunks\">\n            <button id=\"previousChunk\" type=\"button\">← Previous</button>\n            <div class=\"chunk-center\"><span class=\"chunk-indicator\" id=\"chunkIndicator\">Part 1 of 1</span><div class=\"chunk-dots\" id=\"chunkDots\" aria-hidden=\"true\"></div></div>\n            <button id=\"nextChunk\" type=\"button\">Next →</button>\n          </nav>\n          <div class=\"empty-state\" id=\"emptyState\">Add a passage on the left to begin.</div>\n        </div>\n\n        <div class=\"practice-footer\"><p id=\"nextStepHint\">When the words feel familiar, try fewer cues.</p><button class=\"advance\" id=\"advanceStage\" type=\"button\">Try Fade →</button></div>\n        <section class=\"recall\" aria-labelledby=\"recall-title\">\n          <div class=\"recall-head\">\n            <div><h3 id=\"recall-title\">Your turn. From memory.</h3><p class=\"recall-caption\">Recall this part in your own time.</p><p class=\"test-context\" id=\"testContext\"></p></div><span class=\"score\" id=\"score\" aria-live=\"polite\"></span>\n          </div>\n          <div class=\"test-tools\"><div class=\"input-method\" role=\"group\" aria-label=\"Answer method\"><button type=\"button\" id=\"typeAnswer\" aria-pressed=\"true\">Type</button><button type=\"button\" id=\"speakAnswer\" aria-pressed=\"false\">Speak</button></div><label class=\"hide-cues\"><input id=\"hideTestCues\" type=\"checkbox\">Hide the cues</label></div>\n          <div class=\"speech-row\" id=\"speechPanel\" hidden>\n            <button class=\"mic-button\" id=\"micButton\" type=\"button\" aria-pressed=\"false\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 15a3 3 0 0 0 3-3V6a3 3 0 1 0-6 0v6a3 3 0 0 0 3 3Zm-1-9a1 1 0 1 1 2 0v6a1 1 0 1 1-2 0V6Zm7 6a1 1 0 1 1 2 0 8 8 0 0 1-7 7.94V22h3a1 1 0 1 1 0 2H8a1 1 0 1 1 0-2h3v-2.06A8 8 0 0 1 4 12a1 1 0 1 1 2 0 6 6 0 0 0 12 0Z\"/></svg>\n              <span id=\"micLabel\">Start reciting</span>\n            </button>\n            <div class=\"speech-copy\">\n              <p class=\"speech-status\" id=\"speechStatus\" role=\"status\" aria-live=\"polite\">Speak the current chunk and watch your words appear below.</p>\n              <p class=\"speech-note\">FLOW does not save your audio. Speech recognition is handled by your browser and may require microphone permission.</p>\n            </div>\n          </div>\n          <label class=\"sr-only\" for=\"recallText\">Your recalled passage</label>\n          <textarea id=\"recallText\" placeholder=\"What comes next? Type the words you remember…\" spellcheck=\"false\" maxlength=\"12000\"></textarea>\n          <div class=\"recall-actions\">\n            <button class=\"check\" id=\"checkBtn\" type=\"button\">Check recall</button>\n            <button class=\"clear\" id=\"clearBtn\" type=\"button\">Start over</button>\n          </div>\n          <div class=\"feedback\" id=\"feedback\">\n            <div class=\"result-stats\"><div><strong id=\"correctCount\">0</strong>Correct</div><div><strong id=\"missingCount\">0</strong>Missing</div><div><strong id=\"extraCount\">0</strong>Extra / different</div></div>\n            <div class=\"feedback-summary\" id=\"feedbackSummary\"></div>\n            <div class=\"feedback-words\" id=\"feedbackWords\"></div>\n            <div class=\"feedback-legend\"><span class=\"correct\">Correct</span><span class=\"missing\">+ Missing</span><span class=\"wrong\">Extra / different</span></div>\n            <div class=\"result-actions\"><button class=\"clear\" id=\"retryRecall\" type=\"button\">Try again</button><button class=\"advance\" id=\"continueRecall\" type=\"button\">Continue →</button></div>\n          </div>\n        </section>\n      </section>\n    </div>\n  </main>\n  <button class=\"settings-button focus-exit\" id=\"exitFocus\" type=\"button\">Exit focus · Esc</button>\n\n  <dialog class=\"dialog-shell library-dialog\" id=\"libraryDialog\" aria-labelledby=\"libraryTitle\">\n    <div class=\"dialog-head\"><div><h2 id=\"libraryTitle\">Your passages</h2><p>Save once. Practise a little at a time.</p></div><button class=\"dialog-close\" type=\"button\" data-close-dialog aria-label=\"Close passages\">×</button></div>\n    <div class=\"dialog-body\">\n      <div class=\"library-toolbar\"><p id=\"libraryCount\"></p><button class=\"text-action\" id=\"selectAllPassages\" type=\"button\">Select all</button></div>\n      <div class=\"library-list\" id=\"libraryList\"></div>\n      <details class=\"import-box\" id=\"importBox\"><summary>Add passages</summary>\n        <label for=\"importText\">Paste your text</label><textarea id=\"importText\" maxlength=\"200000\" placeholder=\"Paste several paragraphs, a speech, or your study notes…\"></textarea>\n        <label for=\"importSplit\">Create a passage for</label><select id=\"importSplit\"><option value=\"paragraphs\">Each paragraph (blank line between)</option><option value=\"separator\">Each section separated by ---</option><option value=\"whole\">The entire text</option></select>\n        <p class=\"hint\">Use a # Heading on the first line to name a passage. Long passages are divided into short practice parts.</p>\n        <ol class=\"import-preview\" id=\"importPreview\"></ol><p class=\"hint\" id=\"importStatus\" role=\"status\"></p><button class=\"check\" id=\"saveImport\" type=\"button\" disabled>Save passages</button>\n      </details>\n      <p class=\"hint\">Stored in this browser. Your library and place in each passage return when you reopen FLOW.</p>\n    </div>\n    <div class=\"library-footer\"><p id=\"selectionCount\">0 selected</p><button class=\"advance\" id=\"practiceSelected\" type=\"button\">Practise selected →</button></div>\n  </dialog>\n\n  <dialog class=\"dialog-shell\" id=\"settingsDialog\" aria-labelledby=\"settingsTitle\">\n    <div class=\"dialog-head\">\n      <div><h2 id=\"settingsTitle\">Settings</h2><p>Optional services and privacy controls.</p></div>\n      <button class=\"dialog-close\" type=\"button\" data-close-dialog aria-label=\"Close settings\">×</button>\n    </div>\n    <div class=\"dialog-body\">\n      <section class=\"settings-card\" aria-labelledby=\"openaiSettingsTitle\">\n        <h3 id=\"openaiSettingsTitle\">OpenAI connection</h3>\n        <p>Add your API key to unlock AI comprehension as a separate practice option.</p>\n        <label for=\"apiKey\">OpenAI API key</label>\n        <div class=\"key-row\">\n          <input id=\"apiKey\" type=\"password\" placeholder=\"sk-…\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\">\n          <button class=\"key-control\" id=\"toggleKey\" type=\"button\" aria-pressed=\"false\">Show</button>\n          <button class=\"key-control\" id=\"forgetKey\" type=\"button\">Remove</button>\n        </div>\n        <p class=\"key-note\"><strong>Session only:</strong> the key stays in this tab and is never saved by FLOW. Use a restricted, temporary project key.</p>\n        <p class=\"ai-enabled-note\">AI comprehension is now available in Practice.</p>\n        <p class=\"ai-status\" id=\"keyStatus\" role=\"status\" aria-live=\"polite\"></p>\n      </section>\n    </div>\n  </dialog>\n\n  <dialog class=\"dialog-shell\" id=\"aiDialog\" aria-labelledby=\"understand-title\">\n    <div class=\"dialog-head\">\n      <div><h2 id=\"understand-title\">Understand before you memorise</h2><p>Clarify the passage before practising exact recall.</p></div>\n      <button class=\"dialog-close\" type=\"button\" data-close-dialog aria-label=\"Close AI comprehension\">×</button>\n    </div>\n    <div class=\"dialog-body\">\n      <section class=\"understand-panel\">\n        <div class=\"understand-head\">\n          <div>\n            <h3>AI comprehension</h3>\n            <p>Ask AI to explain the meaning, structure and important words in your passage.</p>\n          </div>\n          <span class=\"ai-badge\">Optional AI</span>\n        </div>\n        <button class=\"ai-action\" id=\"explainPassage\" type=\"button\">Explain current passage</button>\n        <p class=\"key-note\">Your current passage is sent to OpenAI only when you click Explain.</p>\n        <p class=\"ai-status\" id=\"aiStatus\" role=\"status\" aria-live=\"polite\"></p>\n        <div class=\"ai-result\" id=\"aiResult\" hidden>\n          <div class=\"ai-result-head\">\n            <h4>Meaning before memory</h4>\n            <button class=\"text-action\" id=\"clearExplanation\" type=\"button\">Clear</button>\n          </div>\n          <div class=\"ai-output\" id=\"aiOutput\"></div>\n        </div>\n      </section>\n    </div>\n  </dialog>\n  <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n  <script>\n    (() => {\n      const els = {\n        title: document.querySelector('#passageTitle'),\n        source: document.querySelector('#sourceText'),\n        displayTitle: document.querySelector('#displayTitle'),\n        cue: document.querySelector('#cueContent'),\n        cueHint: document.querySelector('#cueHint'),\n        chunkStat: document.querySelector('#chunkStat'),\n        accuracy: document.querySelector('#accuracyStat'),\n        revealed: document.querySelector('#revealedCount'),\n        chunkIndicator: document.querySelector('#chunkIndicator'),\n        previous: document.querySelector('#previousChunk'),\n        next: document.querySelector('#nextChunk'),\n        stageTitle: document.querySelector('#stageTitle'),\n        stageHelp: document.querySelector('#stageHelp'),\n        stageCount: document.querySelector('#stageCount'),\n        settingsDialog: document.querySelector('#settingsDialog'),\n        aiDialog: document.querySelector('#aiDialog'),\n        openAI: document.querySelector('#openAIComprehension'),\n        apiKey: document.querySelector('#apiKey'),\n        keyStatus: document.querySelector('#keyStatus'),\n        explainButton: document.querySelector('#explainPassage'),\n        aiStatus: document.querySelector('#aiStatus'),\n        aiResult: document.querySelector('#aiResult'),\n        aiOutput: document.querySelector('#aiOutput'),\n        micButton: document.querySelector('#micButton'),\n        micLabel: document.querySelector('#micLabel'),\n        speechStatus: document.querySelector('#speechStatus'),\n        recall: document.querySelector('#recallText'),\n        score: document.querySelector('#score'),\n        feedback: document.querySelector('#feedback'),\n        feedbackSummary: document.querySelector('#feedbackSummary'),\n        feedbackWords: document.querySelector('#feedbackWords'),\n        toast: document.querySelector('#toast'),\n        focusButton: document.querySelector('#focusMode')\n      };\n\n      const stages = {\n        full: ['Read for meaning', 'Read the phrase aloud and notice its natural rhythm.', 'Stage 1 of 4', 'Read this phrase aloud twice.'],\n        fade: ['Build the pathway', 'Alternate between visible words and initials. Supply the missing words aloud.', 'Stage 2 of 4', 'Full words and initials alternate. Tap an initial if needed.'],\n        letters: ['Initial-letter retrieval', 'Say each word aloud. Tap a letter only when you get stuck.', 'Stage 3 of 4', 'Tap a letter to reveal its word.'],\n        cold: ['Recall without cues', 'Recite the phrase from memory, then type it below to check yourself.', 'Stage 4 of 4', 'Only punctuation and word positions remain.']\n      };\n\n      let chunks = [];\n      let tokens = [];\n      let currentChunk = 0;\n      let mode = 'letters';\n      let revealed = new Set();\n      let lastExplainedSource = '';\n      let speechRecognition;\n      let isListening = false;\n      let scoreSpeechOnEnd = false;\n      let finalTranscript = '';\n      let toastTimer;\n      const checkedParts = new Set();\n      const stageOrder = ['full', 'fade', 'letters', 'cold'];\n      const advanceButton = document.querySelector('#advanceStage');\n      let saveTimer;\n      let library = [];\n      let activeId = null;\n      let queue = [];\n      let selectedPassages = new Set();\n      let loadingPassage = false;\n      let testHintsUsed = false;\n      const libraryDialog = document.querySelector('#libraryDialog');\n\n      function persistLibrary() {\n        try {\n          localStorage.setItem('flow-library-v1', JSON.stringify({ entries: library, activeId, queue }));\n          document.querySelector('#savedStatus').textContent = 'Saved on this device';\n          return true;\n        } catch (_) {\n          document.querySelector('#savedStatus').textContent = 'Storage full · changes not saved';\n          showToast('Browser storage is unavailable or full. Keep a copy of your text.');\n          return false;\n        }\n      }\n\n      function makePassage(title, source) {\n        return { id: crypto.randomUUID(), title, source, part: 0, stage: 'full', checked: [] };\n      }\n\n      function persistProgress() {\n        if (loadingPassage) return;\n        const passage = library.find(item => item.id === activeId);\n        if (!passage) return;\n        passage.part = currentChunk;\n        passage.stage = mode;\n        passage.checked = [...checkedParts];\n        persistLibrary();\n      }\n\n      function renderQueue() {\n        const select = document.querySelector('#queueSelect');\n        select.replaceChildren();\n        queue.forEach(id => {\n          const item = library.find(passage => passage.id === id);\n          if (!item) return;\n          const option = document.createElement('option');\n          option.value = id;\n          option.textContent = item.title;\n          select.append(option);\n        });\n        select.value = activeId;\n        document.querySelector('#sessionQueue').hidden = !queue.length;\n        document.querySelector('#queueLabel').textContent = `Passage ${Math.max(0, queue.indexOf(activeId)) + 1} of ${queue.length}`;\n        document.querySelector('#nextPassage').disabled = queue.indexOf(activeId) >= queue.length - 1;\n      }\n\n      function loadPassage(id, activate = true) {\n        clearTimeout(saveTimer);\n        const item = library.find(passage => passage.id === id);\n        if (!item) return;\n        loadingPassage = true;\n        activeId = id;\n        els.title.value = item.title;\n        els.source.value = item.source;\n        chunks = splitIntoChunks(item.source);\n        els.displayTitle.textContent = item.title;\n        checkedParts.clear();\n        (item.checked || []).forEach(index => checkedParts.add(index));\n        setChunk(item.part || 0);\n        setMode(stageOrder.includes(item.stage) ? item.stage : 'full');\n        els.aiOutput.textContent = '';\n        els.aiResult.hidden = true;\n        lastExplainedSource = '';\n        setAIStatus('');\n        updateEditor();\n        renderQueue();\n        loadingPassage = false;\n        persistLibrary();\n        if (activate) {\n          document.body.classList.add('session-active');\n          document.querySelector('.practice-panel').scrollIntoView({ behavior: 'smooth', block: 'start' });\n        }\n      }\n\n      function updateSelection() {\n        document.querySelector('#selectionCount').textContent = `${selectedPassages.size} selected · library order`;\n        document.querySelector('#practiceSelected').disabled = !selectedPassages.size;\n        document.querySelector('#selectAllPassages').textContent = selectedPassages.size === library.length ? 'Deselect all' : 'Select all';\n      }\n\n      function renderLibrary() {\n        const list = document.querySelector('#libraryList');\n        list.replaceChildren();\n        document.querySelector('#libraryCount').textContent = `${library.length} saved ${library.length === 1 ? 'passage' : 'passages'}`;\n        library.forEach(item => {\n          const label = document.createElement('label');\n          label.className = 'library-item';\n          const checkbox = document.createElement('input');\n          checkbox.type = 'checkbox';\n          checkbox.checked = selectedPassages.has(item.id);\n          checkbox.addEventListener('change', () => {\n            if (checkbox.checked) selectedPassages.add(item.id); else selectedPassages.delete(item.id);\n            updateSelection();\n          });\n          const copy = document.createElement('div');\n          const title = document.createElement('strong');\n          title.textContent = item.title;\n          const preview = document.createElement('small');\n          preview.className = 'preview-text';\n          preview.textContent = item.source.slice(0, 180);\n          const meta = document.createElement('small');\n          const parts = splitIntoChunks(item.source).length;\n          meta.textContent = `${normalizeWords(item.source).length} words · ${parts} ${parts === 1 ? 'part' : 'parts'} · ${(item.checked || []).length} recalled`;\n          copy.append(title, preview, meta);\n          label.append(checkbox, copy);\n          list.append(label);\n        });\n        updateSelection();\n      }\n\n      function openLibrary() {\n        savePassage();\n        selectedPassages = new Set(queue);\n        renderLibrary();\n        libraryDialog.showModal();\n      }\n\n      function parseImport() {\n        const raw = document.querySelector('#importText').value.trim();\n        if (!raw) return [];\n        const split = document.querySelector('#importSplit').value;\n        const texts = split === 'whole' ? [raw] : raw.split(split === 'separator' ? /^\\s*---+\\s*$/m : /\\r?\\n\\s*\\r?\\n/);\n        return texts.map(text => {\n          text = text.trim();\n          const heading = text.match(/^#\\s+([^\\n]+)\\r?\\n([\\s\\S]*)$/);\n          const source = heading ? heading[2].trim() : text;\n          const title = heading ? heading[1].trim() : source.split(/\\s+/).slice(0, 7).join(' ') + (source.split(/\\s+/).length > 7 ? '…' : '');\n          return { title, source };\n        }).filter(item => normalizeWords(item.source).length);\n      }\n\n      function previewImport() {\n        const items = parseImport();\n        const preview = document.querySelector('#importPreview');\n        preview.replaceChildren();\n        items.slice(0, 50).forEach(item => {\n          const li = document.createElement('li');\n          li.textContent = `${item.title} · ${normalizeWords(item.source).length} words`;\n          preview.append(li);\n        });\n        document.querySelector('#importStatus').textContent = items.length ? `${items.length} passages ready${items.length > 50 ? ' (first 50 shown)' : ''}. Existing duplicates will be skipped.` : 'Paste text to preview your passages.';\n        document.querySelector('#saveImport').disabled = !items.length;\n      }\n\n      function continuePractice() {\n        if (currentChunk < chunks.length - 1) { setChunk(currentChunk + 1); setMode('full'); }\n        else if (queue.indexOf(activeId) < queue.length - 1) loadPassage(queue[queue.indexOf(activeId) + 1]);\n        else { openLibrary(); showToast('End of your selection. Choose what to practise next.'); }\n      }\n\n      const isWord = value => /[\\p{L}\\p{M}\\p{N}]/u.test(value);\n\n      function tokenize(text) {\n        return text.match(/[\\p{L}\\p{M}]+(?:['’][\\p{L}\\p{M}]+)?|\\p{N}+(?:[.,]\\p{N}+)*|[^\\p{L}\\p{M}\\p{N}\\s]+|\\s+/gu) || [];\n      }\n\n      function normalizeWords(text) {\n        return (text.toLocaleLowerCase().match(/[\\p{L}\\p{M}\\p{N}]+(?:['’][\\p{L}\\p{M}]+)?/gu) || [])\n          .map(word => word.replace(/’/g, \"'\"));\n      }\n\n      function splitIntoChunks(text) {\n        const sentences = text\n          .split(/(?<=[.!?])\\s+|\\n+/u)\n          .map(value => value.trim())\n          .filter(Boolean)\n          .flatMap(sentence => {\n            // Bound each practice part, including long sentences without punctuation.\n            const pieces = []; let part = ''; let words = 0;\n            tokenize(sentence).forEach(token => {\n              if (isWord(token) && words === 26) { pieces.push(part.trim()); part = ''; words = 0; }\n              part += token;\n              if (isWord(token)) words++;\n            });\n            if (part.trim()) pieces.push(part.trim());\n            return pieces;\n          });\n        const result = [];\n        let group = '';\n        sentences.forEach(sentence => {\n          const combined = group ? `${group} ${sentence}` : sentence;\n          if (group && normalizeWords(combined).length > 26) {\n            result.push(group);\n            group = sentence;\n          } else {\n            group = combined;\n          }\n        });\n        if (group) result.push(group);\n        return result.length ? result : [text.trim()];\n      }\n\n      function firstCharacter(value) {\n        const match = value.match(/[\\p{L}\\p{M}\\p{N}]/u);\n        return match ? match[0] : value;\n      }\n\n      function showToast(message) {\n        clearTimeout(toastTimer);\n        els.toast.textContent = message;\n        els.toast.classList.add('show');\n        toastTimer = setTimeout(() => els.toast.classList.remove('show'), 1800);\n      }\n\n      function savePassage() {\n        clearTimeout(saveTimer);\n        const entry = library.find(item => item.id === activeId);\n        if (entry) {\n          if (entry.source !== els.source.value.trim()) { entry.checked = []; entry.part = 0; entry.stage = 'full'; }\n          entry.title = els.title.value.trim() || 'Untitled passage';\n          entry.source = els.source.value.trim();\n          persistLibrary();\n        }\n        try {\n          localStorage.setItem('flow-passage', JSON.stringify({ title: els.title.value, source: els.source.value }));\n          document.querySelector('#savedStatus').textContent = 'Saved on this device';\n        } catch (_) {\n          document.querySelector('#savedStatus').textContent = 'Saving unavailable';\n        }\n      }\n\n      function updateEditor() {\n        const words = normalizeWords(els.source.value).length;\n        const parts = words ? splitIntoChunks(els.source.value).length : 0;\n        document.querySelector('#wordCount').textContent = `${words} ${words === 1 ? 'word' : 'words'}`;\n        document.querySelector('#partCount').textContent = `${parts} practice ${parts === 1 ? 'part' : 'parts'}`;\n        document.querySelector('#generateBtn').disabled = words === 0;\n      }\n\n      function updateAdvance() {\n        const index = stageOrder.indexOf(mode);\n        advanceButton.textContent = index < 3 ? `Try ${['Read', 'Fade', 'Initials', 'Recall'][index + 1]} →` : currentChunk < chunks.length - 1 ? 'Next part →' : 'Practise again ↺';\n        document.querySelector('#nextStepHint').textContent = index < 3 ? 'When the words feel familiar, try fewer cues.' : 'Check your recall, then keep practising.';\n      }\n\n      function setAIStatus(message, isError = false) {\n        els.aiStatus.textContent = message;\n        els.aiStatus.classList.toggle('error', isError);\n      }\n\n      function hasValidAPIKey() {\n        return els.apiKey.value.trim().length >= 20;\n      }\n\n      function updateAIAvailability({ announce = false } = {}) {\n        const enabled = hasValidAPIKey();\n        document.body.classList.toggle('ai-enabled', enabled);\n        els.openAI.hidden = !enabled;\n        els.keyStatus.textContent = announce\n          ? (enabled ? 'Key added for this tab. It will be checked when you request an explanation.' : 'Enter your full API key to unlock AI comprehension.')\n          : '';\n        els.keyStatus.classList.toggle('error', announce && !enabled);\n        if (!enabled && els.aiDialog.open) els.aiDialog.close();\n      }\n\n      function extractResponseText(data) {\n        if (typeof data.output_text === 'string' && data.output_text.trim()) return data.output_text.trim();\n        return (data.output || [])\n          .flatMap(item => item && item.type === 'message' ? (item.content || []) : [])\n          .filter(item => item && item.type === 'output_text' && typeof item.text === 'string')\n          .map(item => item.text)\n          .join('\\n')\n          .trim();\n      }\n\n      function setListening(active) {\n        isListening = active;\n        els.micButton.classList.toggle('listening', active);\n        els.micButton.setAttribute('aria-pressed', String(active));\n        els.micLabel.textContent = active ? 'Stop & match' : 'Start reciting';\n      }\n\n      function setupSpeechRecognition() {\n        const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;\n        if (!Recognition) {\n          els.micButton.disabled = true;\n          els.speechStatus.textContent = 'Speech recognition is not available in this browser. You can still type your recall.';\n          return;\n        }\n\n        speechRecognition = new Recognition();\n        speechRecognition.continuous = true;\n        speechRecognition.interimResults = true;\n        speechRecognition.lang = navigator.language || 'en-US';\n\n        speechRecognition.onstart = () => {\n          setListening(true);\n          els.speechStatus.textContent = 'Listening… recite the current chunk, then press Stop & match.';\n        };\n        speechRecognition.onresult = event => {\n          let interim = '';\n          for (let i = event.resultIndex; i < event.results.length; i++) {\n            const words = event.results[i][0].transcript.trim();\n            if (event.results[i].isFinal) finalTranscript += `${words} `;\n            else interim += `${words} `;\n          }\n          els.recall.value = `${finalTranscript}${interim}`.trim();\n        };\n        speechRecognition.onerror = event => {\n          scoreSpeechOnEnd = false;\n          const messages = {\n            'not-allowed': 'Microphone access was not allowed. Enable it for this site or type your recall.',\n            'audio-capture': 'No microphone was found. Connect one or type your recall.',\n            'no-speech': 'No speech was detected. Press the microphone and try again.',\n            'network': 'Speech recognition could not reach the browser speech service.'\n          };\n          els.speechStatus.textContent = messages[event.error] || 'Speech recognition stopped unexpectedly. Please try again.';\n        };\n        speechRecognition.onend = () => {\n          setListening(false);\n          if (scoreSpeechOnEnd && els.recall.value.trim()) {\n            checkRecall();\n            els.speechStatus.textContent = 'Recitation matched against the current chunk. Review the result below.';\n          }\n          scoreSpeechOnEnd = false;\n        };\n      }\n\n      function toggleSpeechRecognition() {\n        if (!speechRecognition) return;\n        if (isListening) {\n          els.speechStatus.textContent = 'Finishing your transcript…';\n          speechRecognition.stop();\n          return;\n        }\n        finalTranscript = '';\n        els.recall.value = '';\n        els.score.textContent = '';\n        els.feedback.classList.remove('visible');\n        els.accuracy.textContent = 'Not tested';\n        scoreSpeechOnEnd = true;\n        try { speechRecognition.start(); }\n        catch {\n          scoreSpeechOnEnd = false;\n          els.speechStatus.textContent = 'The microphone is already starting. Please try again in a moment.';\n        }\n      }\n\n      async function explainPassage() {\n        const apiKey = els.apiKey.value.trim();\n        const passage = els.source.value.trim();\n        if (!apiKey || apiKey.length < 20) {\n          setAIStatus('Add a valid OpenAI API key in Settings first.', true);\n          if (els.aiDialog.open) els.aiDialog.close();\n          els.settingsDialog.showModal();\n          els.apiKey.focus();\n          return;\n        }\n        if (!passage) {\n          setAIStatus('Add a passage before asking for an explanation.', true);\n          return;\n        }\n        if (passage.length > 12000) {\n          setAIStatus('This prototype supports passages up to 12,000 characters for AI explanation.', true);\n          return;\n        }\n\n        els.explainButton.disabled = true;\n        els.explainButton.textContent = 'Explaining…';\n        els.aiResult.hidden = true;\n        setAIStatus('Reading for meaning…');\n\n        try {\n          const response = await fetch('/api/explain', {\n            method: 'POST',\n            cache: 'no-store',\n            credentials: 'same-origin',\n            referrerPolicy: 'no-referrer',\n            headers: {\n              'Authorization': `Bearer ${apiKey}`,\n              'Content-Type': 'application/json'\n            },\n            body: JSON.stringify({ passage })\n          });\n\n          const data = await response.json().catch(() => ({}));\n          if (!response.ok) {\n            const message = data && data.error && data.error.message\n              ? data.error.message\n              : `OpenAI returned ${response.status}.`;\n            throw new Error(message);\n          }\n\n          const explanation = extractResponseText(data);\n          if (!explanation) throw new Error('OpenAI returned no explanation. Please try again.');\n          els.aiOutput.textContent = explanation;\n          els.aiResult.hidden = false;\n          lastExplainedSource = passage;\n          setAIStatus('Explanation ready. Make sure it matches your understanding of the passage.');\n        } catch (error) {\n          const message = error instanceof TypeError\n            ? 'Could not reach OpenAI from this browser. Check your connection and try again.'\n            : error.message;\n          setAIStatus(message || 'The explanation could not be generated.', true);\n        } finally {\n          els.explainButton.disabled = false;\n          els.explainButton.textContent = 'Explain passage';\n        }\n      }\n\n      function cueFor(token, wordIndex) {\n        if (revealed.has(wordIndex) || mode === 'full') return token;\n        if (mode === 'fade') return wordIndex % 2 === 0 ? token : firstCharacter(token);\n        if (mode === 'letters') return firstCharacter(token);\n        return '';\n      }\n\n      function updateChunkControls() {\n        const label = `${currentChunk + 1} of ${chunks.length}`;\n        els.chunkStat.textContent = label;\n        els.chunkIndicator.textContent = `Part ${label}`;\n        els.previous.disabled = currentChunk === 0;\n        els.next.disabled = currentChunk === chunks.length - 1;\n        const dots = document.querySelector('#chunkDots');\n        dots.replaceChildren();\n        if (chunks.length <= 20) chunks.forEach((_, index) => {\n          const dot = document.createElement('span');\n          dot.className = index === currentChunk ? 'current' : checkedParts.has(index) ? 'checked' : '';\n          dots.append(dot);\n        });\n        updateAdvance();\n        document.querySelector('#testContext').textContent = `Part ${currentChunk + 1} of ${chunks.length} · ${normalizeWords(chunks[currentChunk] || '').length} words · ${els.displayTitle.textContent}`;\n        document.querySelector('#continueRecall').textContent = currentChunk < chunks.length - 1 ? 'Next part →' : queue.indexOf(activeId) < queue.length - 1 ? 'Next passage →' : 'Back to passages →';\n      }\n\n      function render() {\n        els.cue.replaceChildren();\n        let wordIndex = 0;\n        tokens.forEach(token => {\n          if (!isWord(token)) {\n            els.cue.append(document.createTextNode(token));\n            return;\n          }\n\n          const currentIndex = wordIndex++;\n          if (mode === 'cold' && !revealed.has(currentIndex)) {\n            const blank = document.createElement('button');\n            blank.type = 'button';\n            blank.className = 'word cold-space';\n            blank.setAttribute('aria-label', `Reveal word ${currentIndex + 1}`);\n            blank.addEventListener('click', () => { revealed.add(currentIndex); render(); });\n            els.cue.append(blank);\n            return;\n          }\n\n          const button = document.createElement('button');\n          button.type = 'button';\n          button.className = 'word' + (revealed.has(currentIndex) ? ' revealed' : '');\n          button.textContent = cueFor(token, currentIndex);\n          if (mode === 'full') {\n            const word = document.createElement('span');\n            word.textContent = token;\n            els.cue.append(word);\n            return;\n          }\n          button.title = revealed.has(currentIndex) ? 'Hide this word' : 'Reveal this word';\n          button.setAttribute('aria-label', revealed.has(currentIndex) ? `${token}, revealed` : `Reveal word ${currentIndex + 1}`);\n          button.addEventListener('click', () => {\n            if (revealed.has(currentIndex)) revealed.delete(currentIndex);\n            else revealed.add(currentIndex);\n            render();\n          });\n          els.cue.append(button);\n        });\n        els.revealed.textContent = revealed.size;\n        updateChunkControls();\n      }\n\n      function resetAttempt() {\n        if (isListening && speechRecognition) {\n          scoreSpeechOnEnd = false;\n          speechRecognition.stop();\n        }\n        finalTranscript = '';\n        els.recall.value = '';\n        els.score.textContent = '';\n        els.feedback.classList.remove('visible');\n        els.accuracy.textContent = '—';\n        testHintsUsed = false;\n        document.querySelector('#hideTestCues').checked = false;\n        document.body.classList.remove('test-cues-hidden');\n      }\n\n      function setChunk(index) {\n        currentChunk = Math.max(0, Math.min(chunks.length - 1, index));\n        tokens = tokenize(chunks[currentChunk] || '');\n        revealed.clear();\n        resetAttempt();\n        render();\n        persistProgress();\n      }\n\n      function setMode(nextMode) {\n        mode = nextMode;\n        document.querySelectorAll('.mode-tab').forEach(tab => {\n          tab.setAttribute('aria-selected', String(tab.dataset.mode === mode));\n          tab.tabIndex = tab.dataset.mode === mode ? 0 : -1;\n        });\n        const details = stages[mode];\n        els.stageTitle.textContent = details[0];\n        els.stageHelp.textContent = details[1];\n        els.stageCount.textContent = details[2];\n        els.cueHint.textContent = details[3];\n        document.querySelector('#revealChunk').hidden = mode === 'full';\n        document.querySelector('#resetReveals').hidden = mode === 'full';\n        revealed.clear();\n        resetAttempt();\n        render();\n        persistProgress();\n      }\n\n      function generate({ notify = true, activate = true } = {}) {\n        const source = els.source.value.trim();\n        if (!source) {\n          showToast('Add a passage first');\n          els.source.focus();\n          return;\n        }\n        chunks = splitIntoChunks(source);\n        if (lastExplainedSource && lastExplainedSource !== source) {\n          lastExplainedSource = '';\n          els.aiOutput.textContent = '';\n          els.aiResult.hidden = true;\n          setAIStatus('Passage changed. Generate a new explanation when ready.');\n        }\n        els.displayTitle.textContent = els.title.value.trim() || 'Untitled passage';\n        savePassage();\n        const saved = library.find(item => item.id === activeId);\n        const resumePart = saved?.part || 0;\n        const resumeStage = saved?.stage || 'full';\n        checkedParts.clear();\n        (saved?.checked || []).forEach(index => checkedParts.add(index));\n        loadingPassage = true;\n        setChunk(resumePart);\n        setMode(resumeStage);\n        loadingPassage = false;\n        persistProgress();\n        renderQueue();\n        if (activate) document.body.classList.add('session-active');\n        if (activate) document.querySelector('.practice-panel').scrollIntoView({ behavior: 'smooth', block: 'start' });\n        if (notify) showToast(`${chunks.length} practice ${chunks.length === 1 ? 'part' : 'parts'} ready`);\n      }\n\n      function sequenceDiff(expected, actual) {\n        const rows = expected.length + 1;\n        const cols = actual.length + 1;\n        const table = Array.from({ length: rows }, () => Array(cols).fill(0));\n        for (let i = expected.length - 1; i >= 0; i--) {\n          for (let j = actual.length - 1; j >= 0; j--) {\n            table[i][j] = expected[i] === actual[j]\n              ? table[i + 1][j + 1] + 1\n              : Math.max(table[i + 1][j], table[i][j + 1]);\n          }\n        }\n\n        const operations = [];\n        let i = 0;\n        let j = 0;\n        while (i < expected.length || j < actual.length) {\n          if (i < expected.length && j < actual.length && expected[i] === actual[j]) {\n            operations.push({ type: 'correct', word: actual[j] });\n            i++; j++;\n          } else if (i < expected.length && (j >= actual.length || table[i + 1][j] >= table[i][j + 1])) {\n            operations.push({ type: 'missing', word: expected[i] });\n            i++;\n          } else {\n            operations.push({ type: 'wrong', word: actual[j] });\n            j++;\n          }\n        }\n        return operations;\n      }\n\n      function checkRecall() {\n        const expected = normalizeWords(chunks[currentChunk] || '');\n        const actual = normalizeWords(els.recall.value);\n        if (actual.length > 1200) { showToast('Check just the current part (up to 1,200 words per attempt).'); return; }\n        if (!actual.length) {\n          showToast('Type what you remember first');\n          els.recall.focus();\n          return;\n        }\n\n        const operations = sequenceDiff(expected, actual);\n        const correct = operations.filter(item => item.type === 'correct').length;\n        els.feedbackWords.replaceChildren();\n        operations.forEach(item => {\n          const chip = document.createElement('span');\n          chip.className = item.type;\n          chip.textContent = item.type === 'missing' ? `+ ${item.word}` : item.word;\n          chip.title = item.type === 'missing' ? 'Missing from your answer' : item.type === 'wrong' ? 'Extra or different word' : 'Correct';\n          els.feedbackWords.append(chip);\n        });\n\n        const extras = operations.filter(item => item.type === 'wrong').length;\n        const exact = correct === expected.length && extras === 0;\n        const rawPercent = expected.length ? Math.round((correct / (expected.length + extras)) * 100) : 0;\n        const percent = exact ? 100 : Math.min(99, rawPercent);\n        els.score.textContent = `${percent}% exact`;\n        els.accuracy.textContent = `${percent}%`;\n        els.feedbackSummary.textContent = exact\n          ? (mode === 'cold' ? 'Every word, in order. Well remembered.' : 'Every word matches. Ready to try with fewer cues?')\n          : `${correct} of ${expected.length} words in order${extras ? ` · ${extras} extra or different` : ''}. Review the marked words and try again.`;\n        if (exact && !testHintsUsed && !revealed.size && (mode === 'cold' || document.querySelector('#hideTestCues').checked)) checkedParts.add(currentChunk);\n        document.querySelector('#correctCount').textContent = correct;\n        document.querySelector('#missingCount').textContent = expected.length - correct;\n        document.querySelector('#extraCount').textContent = extras;\n        persistProgress();\n        updateChunkControls();\n        els.feedback.classList.add('visible');\n      }\n\n      document.querySelector('#generateBtn').addEventListener('click', () => generate());\n      document.querySelector('#openLibrary').addEventListener('click', openLibrary);\n      document.querySelector('#libraryInvite').addEventListener('click', openLibrary);\n      document.querySelector('#selectAllPassages').addEventListener('click', () => {\n        selectedPassages = selectedPassages.size === library.length ? new Set() : new Set(library.map(item => item.id));\n        renderLibrary();\n      });\n      document.querySelector('#importText').addEventListener('input', previewImport);\n      document.querySelector('#importSplit').addEventListener('change', previewImport);\n      document.querySelector('#saveImport').addEventListener('click', () => {\n        const items = parseImport();\n        const previousLength = library.length;\n        let skipped = 0;\n        items.forEach(item => {\n          if (library.some(saved => saved.source === item.source)) { skipped++; return; }\n          const entry = makePassage(item.title, item.source);\n          library.push(entry);\n          selectedPassages.add(entry.id);\n        });\n        if (!persistLibrary()) {\n          library.splice(previousLength).forEach(item => selectedPassages.delete(item.id));\n          document.querySelector('#importStatus').textContent = 'Could not save. Your pasted text is still here; copy it before leaving.';\n          return;\n        }\n        renderLibrary();\n        document.querySelector('#importText').value = '';\n        previewImport();\n        document.querySelector('#importStatus').textContent = `${library.length - previousLength} saved${skipped ? ` · ${skipped} duplicates skipped` : ''}. Select passages above to begin.`;\n      });\n      document.querySelector('#practiceSelected').addEventListener('click', () => {\n        if (!selectedPassages.size) return;\n        queue = library.filter(item => selectedPassages.has(item.id)).map(item => item.id);\n        libraryDialog.close();\n        loadPassage(queue[0]);\n      });\n      document.querySelector('#queueSelect').addEventListener('change', event => loadPassage(event.target.value));\n      document.querySelector('#nextPassage').addEventListener('click', () => {\n        const next = queue[queue.indexOf(activeId) + 1];\n        if (next) loadPassage(next);\n      });\n      function chooseAnswerMethod(speak) {\n        document.querySelector('#typeAnswer').setAttribute('aria-pressed', String(!speak));\n        document.querySelector('#speakAnswer').setAttribute('aria-pressed', String(speak));\n        document.querySelector('#speechPanel').hidden = !speak;\n        if (!speak && isListening) { scoreSpeechOnEnd = false; speechRecognition.stop(); }\n        els.recall.placeholder = speak ? 'Your transcript will appear here. You can edit it before checking.' : 'What comes next? Type the words you remember…';\n        if (!speak) els.recall.focus();\n      }\n      document.querySelector('#typeAnswer').addEventListener('click', () => chooseAnswerMethod(false));\n      document.querySelector('#speakAnswer').addEventListener('click', () => chooseAnswerMethod(true));\n      document.querySelector('#hideTestCues').addEventListener('change', event => {\n        document.body.classList.toggle('test-cues-hidden', event.target.checked);\n        if (!event.target.checked) testHintsUsed = true;\n      });\n      document.querySelector('#retryRecall').addEventListener('click', () => { resetAttempt(); els.recall.focus(); });\n      document.querySelector('#continueRecall').addEventListener('click', continuePractice);\n      els.micButton.addEventListener('click', toggleSpeechRecognition);\n      document.querySelector('#openSettings').addEventListener('click', () => {\n        els.settingsDialog.showModal();\n        requestAnimationFrame(() => els.apiKey.focus());\n      });\n      els.openAI.addEventListener('click', () => {\n        if (!hasValidAPIKey()) {\n          els.settingsDialog.showModal();\n          requestAnimationFrame(() => els.apiKey.focus());\n          return;\n        }\n        els.aiDialog.showModal();\n      });\n      document.querySelectorAll('[data-close-dialog]').forEach(button => button.addEventListener('click', () => button.closest('dialog').close()));\n      document.querySelectorAll('dialog').forEach(dialog => dialog.addEventListener('click', event => {\n        if (event.target === dialog) dialog.close();\n      }));\n      document.querySelector('#toggleKey').addEventListener('click', event => {\n        const show = els.apiKey.type === 'password';\n        els.apiKey.type = show ? 'text' : 'password';\n        event.currentTarget.textContent = show ? 'Hide' : 'Show';\n        event.currentTarget.setAttribute('aria-pressed', String(show));\n      });\n      els.explainButton.addEventListener('click', explainPassage);\n      els.apiKey.addEventListener('keydown', event => {\n        if (event.key === 'Enter') {\n          event.preventDefault();\n          updateAIAvailability({ announce: true });\n        }\n      });\n      els.apiKey.addEventListener('input', () => updateAIAvailability({ announce: true }));\n      document.querySelector('#clearExplanation').addEventListener('click', () => {\n        els.aiOutput.textContent = '';\n        els.aiResult.hidden = true;\n        setAIStatus('Explanation cleared. Your API key remains only in this tab.');\n      });\n      document.querySelector('#forgetKey').addEventListener('click', () => {\n        els.apiKey.value = '';\n        els.apiKey.type = 'password';\n        document.querySelector('#toggleKey').textContent = 'Show';\n        document.querySelector('#toggleKey').setAttribute('aria-pressed', 'false');\n        updateAIAvailability();\n        els.keyStatus.textContent = 'API key removed from this tab.';\n        els.keyStatus.classList.remove('error');\n      });\n      document.querySelector('#editPassage').addEventListener('click', () => {\n        document.body.classList.remove('session-active', 'focus-mode');\n        els.focusButton.textContent = 'Focus mode';\n        document.querySelector('.setup-panel').scrollIntoView({ behavior: 'smooth', block: 'start' });\n        els.title.focus();\n      });\n      els.focusButton.addEventListener('click', () => {\n        const active = document.body.classList.toggle('focus-mode');\n        els.focusButton.textContent = active ? 'Exit focus' : 'Focus mode';\n      });\n      document.querySelector('#exitFocus').addEventListener('click', () => {\n        document.body.classList.remove('focus-mode');\n        els.focusButton.textContent = 'Focus mode';\n        els.focusButton.focus();\n      });\n      advanceButton.addEventListener('click', () => {\n        const index = stageOrder.indexOf(mode);\n        if (index < 3) setMode(stageOrder[index + 1]);\n        else {\n          continuePractice();\n        }\n      });\n      document.querySelectorAll('.mode-tab').forEach(tab => {\n        tab.addEventListener('click', () => setMode(tab.dataset.mode));\n        tab.addEventListener('keydown', event => {\n          const index = stageOrder.indexOf(mode);\n          const next = event.key === 'ArrowRight' ? (index + 1) % 4 : event.key === 'ArrowLeft' ? (index + 3) % 4 : event.key === 'Home' ? 0 : event.key === 'End' ? 3 : -1;\n          if (next < 0) return;\n          event.preventDefault();\n          setMode(stageOrder[next]);\n          document.querySelector(`[data-mode=\"${mode}\"]`).focus();\n        });\n      });\n      document.querySelector('#revealChunk').addEventListener('click', () => {\n        revealed = new Set(tokens.filter(isWord).map((_, index) => index));\n        render();\n      });\n      document.querySelector('#resetReveals').addEventListener('click', () => {\n        revealed.clear();\n        render();\n      });\n      els.previous.addEventListener('click', () => setChunk(currentChunk - 1));\n      els.next.addEventListener('click', () => setChunk(currentChunk + 1));\n      document.querySelector('#checkBtn').addEventListener('click', checkRecall);\n      document.querySelector('#clearBtn').addEventListener('click', () => {\n        resetAttempt();\n        els.speechStatus.textContent = 'Speak the current chunk and watch your words appear below.';\n        els.recall.focus();\n      });\n      [els.title, els.source].forEach(input => input.addEventListener('input', () => {\n        updateEditor();\n        clearTimeout(saveTimer);\n        document.querySelector('#savedStatus').textContent = 'Saving…';\n        saveTimer = setTimeout(savePassage, 400);\n      }));\n      els.recall.addEventListener('input', () => {\n        els.score.textContent = '';\n        els.accuracy.textContent = '—';\n        els.feedback.classList.remove('visible');\n      });\n      els.recall.addEventListener('keydown', event => {\n        if ((event.metaKey || event.ctrlKey) && event.key === 'Enter') checkRecall();\n      });\n\n      [els.title, els.source].forEach(input => input.addEventListener('keydown', event => {\n        if ((event.metaKey || event.ctrlKey) && event.key === 'Enter') generate();\n      }));\n      document.addEventListener('keydown', event => {\n        if (event.key === 'Escape' && document.body.classList.contains('focus-mode')) {\n          document.body.classList.remove('focus-mode');\n          els.focusButton.textContent = 'Focus mode';\n        }\n      });\n\n      try {\n        const savedLibrary = JSON.parse(localStorage.getItem('flow-library-v1'));\n        if (savedLibrary && Array.isArray(savedLibrary.entries)) {\n          library = savedLibrary.entries.filter(item => item && typeof item.id === 'string' && typeof item.source === 'string' && typeof item.title === 'string');\n          activeId = library.some(item => item.id === savedLibrary.activeId) ? savedLibrary.activeId : library[0]?.id;\n          queue = Array.isArray(savedLibrary.queue) ? savedLibrary.queue.filter(id => library.some(item => item.id === id)) : [];\n        }\n      } catch (_) {}\n      try {\n        const saved = JSON.parse(localStorage.getItem('flow-passage'));\n        if (saved && saved.source) {\n          els.title.value = saved.title || 'Untitled passage';\n          els.source.value = saved.source;\n        }\n      } catch (_) {}\n\n      if (!library.length) {\n        const item = makePassage(els.title.value.trim() || 'Untitled passage', els.source.value.trim());\n        library.push(item);\n        activeId = item.id;\n      }\n      if (!queue.includes(activeId)) queue = [activeId];\n      loadPassage(activeId, false);\n      updateEditor();\n      setupSpeechRecognition();\n      updateAIAvailability();\n    })();\n  </script>\n</body>\n</html>\n";

const securityHeaders = {
  'content-security-policy': "default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'self'",
  'referrer-policy': 'no-referrer',
  'x-content-type-options': 'nosniff',
  'x-frame-options': 'SAMEORIGIN'
};

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...securityHeaders, 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' }
  });
}

async function explain(request) {
  if (request.method !== 'POST') return json({ error: { message: 'Method not allowed.' } }, 405);
  const authorization = request.headers.get('authorization') || '';
  if (!authorization.startsWith('Bearer ') || authorization.length < 28) {
    return json({ error: { message: 'A valid OpenAI API key is required.' } }, 401);
  }

  let body;
  try { body = await request.json(); }
  catch { return json({ error: { message: 'Invalid request body.' } }, 400); }
  const passage = typeof body?.passage === 'string' ? body.passage.trim() : '';
  if (!passage) return json({ error: { message: 'A passage is required.' } }, 400);
  if (passage.length > 12000) return json({ error: { message: 'Passage exceeds the 12,000 character limit.' } }, 413);

  try {
    const upstream = await fetch('https://api.openai.com/v1/responses', {
      method: 'POST',
      headers: { 'authorization': authorization, 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'gpt-5-mini',
        store: false,
        max_output_tokens: 900,
        instructions: 'You are a concise learning coach. Help the learner understand a passage before memorising it. Explain only what the supplied passage supports. Use plain language and preserve important distinctions. Return four short sections with these exact headings: PLAIN MEANING, STRUCTURE, KEY WORDS, CHECK YOUR UNDERSTANDING. Under the last heading, give exactly two short questions. Do not provide memorisation tricks yet.',
        input: 'Explain this passage for comprehension before memorisation:\n\n' + passage
      })
    });
    const responseBody = await upstream.text();
    return new Response(responseBody, {
      status: upstream.status,
      headers: { ...securityHeaders, 'content-type': upstream.headers.get('content-type') || 'application/json; charset=utf-8', 'cache-control': 'no-store' }
    });
  } catch {
    return json({ error: { message: 'The OpenAI request could not be completed.' } }, 502);
  }
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/api/explain') return explain(request);
    if (request.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
      return new Response(page, { headers: { ...securityHeaders, 'content-type': 'text/html; charset=utf-8' } });
    }
    return new Response('Not found', { status: 404, headers: securityHeaders });
  }
};
